"""Realm Quests art (your painted notice-board sheet): background with the board and its blank posters, progress bar, stamp, pinned tag, wax seal, pushpin, and a red banner kept for later.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# spots in quest_bg.jpg, in its own pixels
LIGHTS = ((605, 135, 46), (1245, 135, 46), (322, 598, 48), (1522, 596, 40), (1582, 538, 40), (1636, 490, 40), (1602, 305, 42))   # torches, candles, lantern
POSTER = (625, 282, 995, 570)         # the big blank poster (current quest)
POSTER2 = (990, 355, 1240, 595)       # the small blank poster (up next)
TAG_AT = (1165, 268)                  # where the pinned "quests done" tag goes (top left)
BOARD_BOTTOM = 625                    # bottom edge of the notice board
BAR_IN = (87 * 700 // 1207, 38 * 700 // 1207, 1115 * 700 // 1207, 89 * 700 // 1207)   # quest_bar: the dark groove (left, top, right, bottom)
STAMP_TILT = 11                       # degrees the painted stamp border leans
PNG = {
  'banner_red': ('png', ''),
  'pushpin': ('png', ''),
  'quest_bar': ('png', ''),
  'quest_bg': ('jpg', ''),
  'quest_tag': ('png', ''),
  'stamp': ('png', ''),
  'wax_seal': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
